import styled from '@emotion/styled';
import { Heading } from 'components/UI';
import { theme } from 'theme';

export const StyledBasicHeader = styled.div({
  display: 'flex',
  alignItems: 'center',
  '.title': {
    marginRight: '8px',
  },
  marginBottom: '16px',
});

interface StyledSubtitleProps {
  $color?: 'black' | 'grey';
}

export const StyledSubtitle = styled(Heading, {
  shouldForwardProp: (propName) => propName !== '$color',
})<StyledSubtitleProps>(({ $color }) => ({
  marginRight: '8px',
  ...($color === 'black' && { color: '#141414' }),
  ...($color === 'grey' && { color: theme.colors.txt.secondary }),
}));
